"""Cuaderno del estudiante, 2.º medio Lengua y Literatura, OA 15 (planificar, escribir, revisar, reescribir y editar en función de contexto, destinatario y propósito) y OA 16 (estilo directo e indirecto).

Todos los textos, mensajes y fuentes son originales e inventados («de ejemplo»); cada ejercicio trae escrito el texto que necesita.
Nota: los títulos de las clases del repositorio son genéricos (reconocer, investigar, planificar, escribir, revisar, editar);
este cuaderno los sigue y los aplica a cada OA. En OA 15 se reparten los contenidos del OA así: registro y persona (clase 1),
recopilar y organizar ideas e intereses del lector (clase 2), plan según género y destinatario (clase 3), coherencia, cohesión y
vocabulario (clase 4), pronombres, conjugaciones, participios y concordancias (clase 5), preposiciones, conectores, ortografía,
presentación y procesador de textos (clase 6).
"""
from __future__ import annotations

from student_lessons import arith, ex, register

OA15 = "LE2M OA 15"
OA16 = "LE2M OA 16"
E = ex

MAT = "Este cuaderno, lápiz y los textos y datos escritos en cada ejercicio. No necesitas libros especiales ni internet."


def task(statement, example, criteria, evidence, errors, feedback):
    return {"statement": statement, "example": example, "criteria": criteria, "evidence": evidence, "errors": errors, "feedback": feedback}


def L(oa, n, use, prior, explain, vocab, worked, mistakes, tiers, ctx, sc, open_task, reinforce, extend, materials=MAT):
    register(
        oa, n, materials=materials, use=use, prior=prior, explain=explain, vocab=vocab,
        worked=[{"title": t, "problem": p, "steps": s, "answer": a} for t, p, s, a in worked],
        mistakes=[{"wrong": w, "why": y, "fix": f} for w, y, f in mistakes],
        tiers=dict(zip(("recovery", "understand", "apply", "reason", "challenge"), tiers)),
        context=ctx, selfcheck=sc, open_task=task(*open_task), reinforce=reinforce, extend=extend,
    )


def Q(q, why, *opts):
    """Pregunta de alternativas: la primera opción es la correcta (el registro la reubica solo)."""
    letters = "ABC"
    stem = q + " " + " ".join(f"{letters[i]}) {o}" for i, o in enumerate(opts))
    return E(stem, f"A) {opts[0]}", why)


